INSERT INTO transfer_targets VALUES(10,'AVL','2026-summer','Modou Kéba Cissé','시세',1944705,'LASK → Aston Villa','CB','RCB','CONFIRMED','00200001420237413X9814X84',60.89999999999999858,31.19999999999999929,6,6.769999999999999574,'cb_defender','Balanced','cb_bpd','Aggressive',0.8559999999999999832,'CONFIRMED incoming: pre-contract signed summer 2025, joins for 2026/27 after a season at LASK. Measured: right-of-centre CB (60.9,31.2), Ball-Playing Defender/Aggressive fit 0.89 — same fit family as Konsa (0.88). Natural RCB cover/heir; Austrian Bundesliga level caveat. [2026-07-15 재확인] RotoWire: 공식 합류 확인(사전계약, LASK에서 2026년 여름 발효). [2026-07-15 3축+스탯 — 유지] 6경기: kp 0·xA .01·듀얼 3.8·태클 1.5·패스 84% — 진전 산출 없는 수비형, cb_defender/Balanced 처방 유지(움직임은 bpd/Aggressive .89로 콘사형 스텝아웃 — 기능축 우선). LASK 리그 수준 캐비앗. [2026-07-28 FC26 통합 확인] 숙련 cb_defender+·cb_stopper+ — bpd 마커 없음, 기능축 처방(cb_defender/Balanced)을 FC26이 지지 — 확정.','https://readastonvilla.com/2026/05/14/modou-keba-cisse-the-future-aston-villa-player-who-is-shining-in-austria/ ; SofaScore API player 1944705 (2026-07-02)','CONFIRMED signing; measured from LASK (league-strength caveat). / 2026-07-15: 공식 완료 확인 — CONFIRMED 유지.','시세',NULL);
INSERT INTO transfer_targets VALUES(13,'AVL','2026-summer','Alysson','알리송',1631879,'Aston Villa (2026-01, Grêmio €10M)','RW','RM','OWNED','001640014X000380003600011',83.20000000000000284,59.70000000000000284,6,6.75,'wm_winger','Balanced','wm_winger','Balanced',0.8349999999999999645,'ALREADY OWNED: joined from Grêmio for €10M in January 2026; young (2006) right winger not yet in the analysis roster. Measured: genuine wide-right (83.2,59.7) — the squad''s only natural touchline RW; fit Inside Forward/Balanced 0.85. Prescription Winger/Attack to use his width+pace profile distinct from McGinn/Bowen half-space types. [2026-07-15 3축+스탯 — 유지] 6경기: xG .10·xA .03·kp .3·듀얼 3.7·드리블 1.0 — 창조 산출 미성숙 직선 윙어, winger/Attack 처방 유지(움직임 최근접은 insidefwd/Balanced .847). [2026-07-29 우측 브리프 정합 검증] 디아비 템플릿 코사인 .839, 침투 서명 전방 0.54·자기진영 0.23(하지무사·음바예보다 낮음 = 침투 빈도 열위), 터치라인 열 0.60 = 스쿼드 유일 천연 터치라인 RW. 함의: 브리프를 부분 충족하는 보유 자원이라 "우측이 절대 공백은 아니다"는 협상 레버리지. 19세로 주전 고정은 리스크.','https://www.fotmob.com/teams/10252/transfers/aston-villa ; SofaScore API player 1631879 (2026-07-02)','OWNED; measured mixes Grêmio+Villa minutes (sample caveat). / 🔄 **[2026-07-31 obs#100 — 커널 교체 후 재산출]** 옛 기준(obs#93·#94 이전) 잔존값을 정정했다. 브라우저에서 툴 `placedMap`·`cmpCos`를 직접 호출해 산출(컨텍스트 노트 2), 회귀 게이트 하지무사 .821 재현 확인. 알리송 RM(x=85): .847 (wm_winger/Attack) → **wm_winger/Balanced 0.835**.',NULL,NULL);
INSERT INTO transfer_targets VALUES(30,'AVL','2026-summer','Tammy Abraham','타미 아브라함',610766,'Aston Villa','ST','ST','OWNED','01855255648X8415422010200',47.39999999999999858,59.0,4,6.849999999999999645,'st_target','Attack','st_false9','Attack',0.5210000000000000186,'ALREADY OWNED: 2026-01-27 베식타슈에서 ~£18m로 빌라 복귀(1일 만에 재이적), 그 시즌 유로파리그 우승. 여름 루머 대상이 아니라 보유 선수(알리송과 동일 케이스) — 사용자 요청으로 OWNED ST 옵션으로 편입. 실측(반시즌 통틀어 45분+ 4경기 전부 ST): 중앙-약간좌측·깊은 풋프린트 (47.4,59.0), 평균 6.85. 최근접 st_false9/Attack 0.52 — 왓킨스(st_advanced 자기커널)·기라시 0.80·브로베이 0.75·파르도 0.87보다 명확히 낮음. 처방은 타깃/홀드업 아키타입 반영 st_target/Attack. 표본 캐비앳: 왓킨스의 로테이션 백업이라 45분+ 경기가 반시즌 4경기뿐이고 전부 교체 출전(추격 상황 드롭) → 깊은 편향된 풋프린트, 선발 표본 아님. [2026-07-15 3축+스탯 — 유지] 6경기: xG .25·3골·kp 1.0·드리블 0 — 타깃형 피니셔, st_target/Attack(공중 플랜B, obs#19) 유지.','https://www.avfc.co.uk/news/2026/january/27/signing-aston-villa-confirm-tammy-abraham-signing/ ; SofaScore API player 610766 (2026-07-03)','OWNED — 이적 루머 아님(2026-01 합류확정 보유선수). 측정 신뢰 MEDIUM(표본 4경기·전부 교체출전·맥락 편향, 45분+ 6경기 미달).',NULL,NULL);
INSERT INTO transfer_targets VALUES(77,'AVL','2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg','CM','LDM','CONFIRMED','33414775548X6447877220320',43.60000000000000142,51.79999999999999716,6,7.620000000000000106,'dm_dlp','Roaming','dm_dlp','Roaming',0.7259999999999999787,'완전 box-to-box, 중앙 전역 커버(온아나 대체). 실측 6경기(분데스리가, 363pt) 중심 tool(44,52). 커널 fit LDM dm_dlp/Roaming 0.812 (RDM는 0.544로 약함 → 좌중앙 성향, LDM 전용). 평균 7.62 최상. [2026-07-14 확정] 빌라 합류 확정(사용자 확인). [2026-07-15 재확인] Romano "here we go": €60m+ 구두합의, 개인조건 완료. 뉴캐슬 £49m 구두합의를 히잭. 아직 공식 발표(메디컬) 전 단계. [2026-07-15 3축+스탯 — 유지] 6경기: 듀얼 7.5(후보군 1위)·xG .18·xA .16·태클 1.8·평점 7.40 — 박투박+창조 겸비(오나나 공백 임무에도 부합), dlp/Roaming 유지. [2026-07-17 재확인] 메디컬 완료(7/16), Romano "몇 시간 내 발표". Visit Rwanda 스폰서 관련 잡음(DRC 가족사) 해소, 5년 계약 — 클럽 레코드 £50m+. [2026-07-18 재확인] 공식 발표 완료(7/17 저녁) — £59.5m(€70m) 클럽 레코드, 장기계약. 뉴캐슬 하이잭 최종 성사. [2026-07-21 멀티포지션] CAM(대표팀 전진 실측 0.817)·LM(재배치 0.700) 행 추가 — 슬롯별 별도 그리드 참조. [2026-07-28 FC26 통합 확인] LDM: 숙련 dm_dlp+·cm_dlp+가 처방과 일치 — 확정. 테크니컬 PS·드리블85.','Romano/Ornstein/Sky Germany 하이잭 보도(€70m 합의 임박); SofaScore player/1518931 (6 Bundesliga ~2026-05-16)','CONFIRMED — 합류 확정. 실측 신뢰 HIGH(6경기 전부 45분+, 363pt, fit 0.812). / 2026-07-15: 구단간·개인 합의 완료, 공식 발표만 대기 — CONFIRMED 유지. / 2026-07-18: 구단 공식 발표 — 완료.','만잠비',NULL);
INSERT INTO transfer_targets VALUES(91,'AVL','2026-summer','João Palhinha',NULL,364612,'Bayern Munich','DM','LDM','HIGH','002112323345365465X611221',53.70000000000000284,44.0,6,6.919999999999999929,'dm_holding','Ball-Winning','dm_widehalf','Build-Up',0.7089999999999999636,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다. [2026-08-08 09시 재확인] 홍콩 친선전(08-07, 바이에른 2-1 승) 종료 후 빌라 SD Damian Vidagany가 Sport Bild에 직접 발언: "We are in talks, but there is currently no agreement." 바이에른 요구 €20-25m, 여전히 가격차 교착 — 단계 진전 없음. HIGH 유지. [2026-08-09 09시 재확인 — HIGH 유지] 빌라가 임대+의무매입옵션(단계적 지불) 구조를 대안으로 모색 중이나 바이에른은 완전이적(€25m) 우선 — 구조 교착 그대로. 선수 본인은 "요구액 인하 없으면 잔류도 감수"라는 입장 유지, 뮌헨 잔류 시 연봉 €10m+보너스 €2m 부담이 빌라 PSR에 걸림돌이라는 재정 분석 추가(신규 사실 아님, 정황 보강). 홍콩 대면협상 이후 추가 협상 진전 보도 없음. [2026-08-10 09시 재확인 — HIGH 유지] 단계·구조 전부 불변(빌라=1년 임대 스톱갭 선호 vs 바이에른=완전이적 €25m 고수). Vidagany 공식 발언 "협상 중이나 현재 합의 없음"이 최신 상태 그대로. [경쟁구도 신규] 뉴캐슬이 팔리냐 경쟁에 참전한다는 보도가 등장 — 단계는 관심 수준이고 빌라는 구단 공식 확인 협상 단계라 §2-1상 빌라 우위 유지, 등급 보정 없음. ⚠️[2026-08-10 자기정정] 이 회차의 갱신 내용은 **발행일 확정 실패**다 — Moretto 건은 TransferFeed "1h ago" 스탬프(수집 시각이지 발행 시각이 아님, §1)에만 근거하고 원문 날짜를 잡지 못했다. §2-0에 따라 last_news_date를 08-09로 되돌린다(STALE 시계는 확정된 보도일로만 움직인다). [2026-08-10 21시 — 경쟁 강도 하향 정정] 어제 기록한 "뉴캐슬 참전"의 실체가 드러났다: **뉴캐슬의 1순위는 마르세유의 Højbjerg이고 팔리냐는 그 대안으로 거론된 것**이다. 즉 뉴캐슬은 팔리냐를 주 타깃으로 쫓고 있지 않다 → §2-1 경쟁 강도를 한 단계 낮춰 읽어야 하며 **빌라 우위가 더 명확**해졌다. 단계는 여전히 불변(Vidagany "협상 중, 합의 없음", 가격 €25m·구조 임대vs완전 교착). ⚠️ 신규 서술: 협상이 **08-12 PSG 슈퍼컵 전에 마무리되지 않을 수 있다**는 전망.','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입. / [2026-08-03] 경쟁 축 캐비앗: 뉴캐슬은 감독 공백으로 집행력 부재 · 자금은 증가 가능 — 두 방향이 상쇄돼 순효과는 미확정.','팔리냐','2026-08-09');
INSERT INTO transfer_targets VALUES(92,'AVL','2026-summer','João Palhinha',NULL,364612,'Bayern Munich','DM','RDM','HIGH','002112323345365465X611221',53.70000000000000284,44.0,6,6.919999999999999929,'dm_holding','Ball-Winning','dm_dlp','Roaming',0.7379999999999999894,'바이에른과 시즌 로그론 + €25m 의무구매옵션 가능성 합의, 잉글랜드 이동 중(오나나 부상 공백 메우기). 온나나 십자인대 부상, 틸레만스 맨유行으로 보강 필요. [2026-07-27 21시 최신화] 로마노/애슬레틱(Tanswell) 경유: 팔리냐가 잉글랜드로 이동해 임대(+콜옵션 €25m) 마무리 단계 — 벤피카를 제치고 빌라가 사실상 확보. 다만 Tanswell은 "완전히 무산된 건 아니지만 빌라가 다른 일들로 바빠 잠시 정체"라고 톤 조절. 바이에른은 매각 강력 희망(€100m 펀드 확보 목적). [2026-07-28 FC26 통합 확인] 숙련 dm_holding+(수비/볼위닝/로밍)가 기능축 처방과 정확 일치 — 확정. DEF83/PHY84/공격성91/태클85·슬라이딩태클/브루저 PS. 캐비앗: 네거티브 PS "부상에 취약함". [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(Sky DE): 7/19 "영국행·합의" 보도 반박 — 합의 없음, 프리시즌 바이에른 합류. 현 상태: 빌라=대여+옵션 고수 vs 바이에른=€25m 완전이적 요구 교착. BILD "빌라가 바이에른의 최유력 매각처". 사우디·터키 관심 있으나 선수는 유럽 잔류 희망(가족). [경쟁구도 2026-07-30] 빌라 우위 — 경쟁 대안(벤피카·스포르팅)은 마르쿠 실바 재결합 등 동기는 있으나 €25m 지불 능력이 없고, 사우디·터키 공식 오퍼는 선수가 거부. 바이에른 SD Freund가 7/28 공개 발언("다음 단계는 다른 곳에서")으로 매각 기조 확정, BILD는 빌라를 최유력 매수처로 서술. 교착 지점은 클럽 경쟁이 아니라 구조(임대+옵션 vs 완전 €25m)와 선수 본인 결정. 선수 선호는 자녀 거주지(포르투갈) 근접이지만 자금이 그 선호를 봉쇄. [경쟁구도 2026-08-01 — 빌라 우위 → **대등**으로 하향] 뉴캐슬 참전: ESPN Brasil(Bruno Andrade 기명)이 뉴캐슬이 브루누 기마랑이스 아스날행 대비 미드필더 2인과 협상 중이며 그중 하나가 팔리냐라고 보도. 뉴캐슬은 기마랑이스 매각 ~€93m(+토날리 €117m 기수령)으로 **지불력이 빌라 £40m 상한(Tanswell)보다 명확히 우위**. 바이에른 측: Falk — 바이에른이 더는 합의를 자신하지 못하며, 선수 본인이 "요구액 미인하 시 잔류도 감수"로 **레버리지를 쥠**. Eberl이 매각 대상 3인에 공개 포함, 완전이적 **€30m 근접액 요구**(07-30 €25m에서 상향). 구조 교착(빌라 임대+옵션 vs 바이에른 완전이적)은 불변. §2-1 보정표상 "경쟁 클럽 우위"가 아니라 "대등"이므로 **등급은 HIGH 유지**. [2026-08-02 경쟁구도 재판정 — 대등 → **빌라 우위**로 되돌린다] ⚠️ **어제(08-01) 하향은 과잉 해석이었다.** 근거로 쓴 ESPN Brasil(Bruno Andrade) 기사는 뉴캐슬이 기마랑이스 대체 **숏리스트 2인**을 추렸고 그중 하나가 팔리냐라는 내용까지이며, **협상 단계라고 쓰지 않았다** — 나는 "지불력 우위(€93m)"를 "단계 우위"로 읽었다. 오늘 독립 확인 결과 **뉴캐슬의 입찰 보도는 없고 관심·숏리스트 단계**이며, 빌라는 **수 주간 바이에른과 협상 중**(돌파구 없음)이다. 단계 비교(협상 > 관심)에서 빌라가 앞선다. ⚠️ 단 오늘 검색은 **빌라의 공식 입찰(formal bid) 제출도 확인하지 못했다** — 스캔 에이전트의 "빌라만 공식 입찰" 서술은 채택하지 않는다. 교착 요인 불변: 빌라 임대+옵션 vs 바이에른 완전이적 €30m 근접, Falk "바이에른이 더는 합의를 자신하지 못한다", 선수는 잔류도 감수 + 사우디 오퍼 거절. [경쟁구도 2026-08-03 22시 — 뉴캐슬 항 하향] ⭐ **에디 하우가 2026-07-31 뉴캐슬 감독직에서 사퇴했다**(구단 공식 발표 + Sky Sports + ESPN = 1티어 3중). 브리스톨 시티전 1-4 패배 직후이고, 사유는 개인 재충전이나 배경으로 **어려운 여름 이적창**(토날리·고든 매각)이 병기된다. 후임 미임명(Jaissle 유력, "advanced stage"), 개막(8/23 리버풀)까지 25일. → **감독 부재 상태의 중원 숏리스트는 집행력이 없다**. 다만 반대 방향 요인이 병존한다: 기마랑이스→아스날 €93m이 성사되면 **자금은 오히려 늘어난다**. 정확한 서술은 **"자금은 늘고 집행 주체는 사라진 상태"**다. ⚠️ 이 사실은 08-03 09시·21시 두 섹션이 모두 놓쳤다 — 경쟁 클럽 링크를 **숏리스트 등재 여부로만** 추적하면 상대 구단의 **제도적 집행력 변화**를 놓친다는 사례로 남긴다. 빌라 등급 HIGH·단계는 불변(병목은 여전히 바이에른의 완전이적 €25~30m 고수). [2026-08-06 22시 갱신 — HIGH 유지, 발행일 확정] 09시에 "Bild 보도·발행일 미확정"으로 남겨둔 건이 확정됐다: Sport1(2026-08-06)·Sport BILD가 바이에른의 **€25m 요구를 빌라가 거부**해 재정 조건에서 교착이라고 보도. 신규 사실 — 양 구단이 **08-07 홍콩 카이탁 친선전(Audi Football Summit)을 계기로 대면 협상**을 갖는다. [반대 신호] 팔리냐 본인이 Abendzeitung에 "바이에른에서 자리를 지키는 것이 계획"이라 발언(단, 측근은 오퍼 청취 지속·바이에른 26/27 1군 명단 제외·스포르팅 디렉터 Freund도 장기 계획 밖임을 인정). 단계는 "협상(교착)" 유지 — 오퍼 제출·개인합의 보도 0건이라 상향 불가. [2026-08-07 09시 재확인 — HIGH 유지, 협상 미개최] 어제 예고된 홍콩 대면 협상은 **아직 열리지 않았다** — 친선전 킥오프가 08-07 14:00 CEST(21:00 KST)이고 독일 매체는 협상을 "경기 전후"로 예고했다. 즉 결과는 오늘 21시 회차의 대상이다(Sport1도 "결과는 아직 없다"고 명시). **08-06 이후 신규 사실 2건**: ⑴ **Eberl(바이에른 단장)이 팔리냐·Boey·Zaragoza에 대해 "바이에른에 미래는 없다"고 공개 발언** — 08-06의 Freund 인정보다 강한 공식 톤. ⑵ **임대+옵션·임대+의무매입 등 대안 구조도 이미 시도됐으나 합의 실패** — 교착이 총액뿐 아니라 구조 협상까지 소진된 상태다. 선수 입장은 변화 없음(잔류가 계획, 측근은 오퍼 청취 지속). 콤파니 중원 서열은 키미히·파블로비치·비쇼프·바라 은디아예. ⚠️ 발행일 함정 회피 1건: givemesport "Villa handed huge boost"(Falk/BILD 경유, 바이에른 호가 인하·임대 수용 가능성)는 **2026-07-21자**라 신선한 진전이 아니다. [2026-08-08 09시 재확인] 홍콩 친선전(08-07, 바이에른 2-1 승) 종료 후 빌라 SD Damian Vidagany가 Sport Bild에 직접 발언: "We are in talks, but there is currently no agreement." 바이에른 요구 €20-25m, 여전히 가격차 교착 — 단계 진전 없음. HIGH 유지. [2026-08-09 09시 재확인 — HIGH 유지] 빌라가 임대+의무매입옵션(단계적 지불) 구조를 대안으로 모색 중이나 바이에른은 완전이적(€25m) 우선 — 구조 교착 그대로. 선수 본인은 "요구액 인하 없으면 잔류도 감수"라는 입장 유지, 뮌헨 잔류 시 연봉 €10m+보너스 €2m 부담이 빌라 PSR에 걸림돌이라는 재정 분석 추가(신규 사실 아님, 정황 보강). 홍콩 대면협상 이후 추가 협상 진전 보도 없음. [2026-08-10 09시 재확인 — HIGH 유지] 단계·구조 전부 불변(빌라=1년 임대 스톱갭 선호 vs 바이에른=완전이적 €25m 고수). Vidagany 공식 발언 "협상 중이나 현재 합의 없음"이 최신 상태 그대로. [경쟁구도 신규] 뉴캐슬이 팔리냐 경쟁에 참전한다는 보도가 등장 — 단계는 관심 수준이고 빌라는 구단 공식 확인 협상 단계라 §2-1상 빌라 우위 유지, 등급 보정 없음. ⚠️[2026-08-10 자기정정] 이 회차의 갱신 내용은 **발행일 확정 실패**다 — Moretto 건은 TransferFeed "1h ago" 스탬프(수집 시각이지 발행 시각이 아님, §1)에만 근거하고 원문 날짜를 잡지 못했다. §2-0에 따라 last_news_date를 08-09로 되돌린다(STALE 시계는 확정된 보도일로만 움직인다). [2026-08-10 21시 — 경쟁 강도 하향 정정] 어제 기록한 "뉴캐슬 참전"의 실체가 드러났다: **뉴캐슬의 1순위는 마르세유의 Højbjerg이고 팔리냐는 그 대안으로 거론된 것**이다. 즉 뉴캐슬은 팔리냐를 주 타깃으로 쫓고 있지 않다 → §2-1 경쟁 강도를 한 단계 낮춰 읽어야 하며 **빌라 우위가 더 명확**해졌다. 단계는 여전히 불변(Vidagany "협상 중, 합의 없음", 가격 €25m·구조 임대vs완전 교착). ⚠️ 신규 서술: 협상이 **08-12 PSG 슈퍼컵 전에 마무리되지 않을 수 있다**는 전망.','https://www.transferfeed.com/clubs/aston-villa/15; Record(PT); GiveMeSport; SportsMole ; Plettenberg/Sky DE via onefootball·readastonvilla (2026-07-24, 재검증 07-26); Sports Mole; Yahoo Sports/Bavarian Football Works("on verge"); Jacob Tanswell(Athletic, 팟캐스트); CaughtOffside ; https://www.sport1.de/news/transfermarkt/2026/08/fc-bayern-entscheidet-sich-der-palhinha-poker-in-hongkong (2026-08-06) ; https://bulinews.com/bayern-and-aston-villa-hold-palhinha-talks-after-pre-season-friendly (Sport BILD 경유) ; https://fcbinside.de/2026/08/06/testspiel-wird-zur-transfer-buehne-jetzt-kommt-bewegung-in-den-palhinha-poker/ ; https://www.90min.de/palhinha-poker-vor-neuer-wende-bayern-testet-gegen-interessenten','HIGH 유지 — 임대+콜옵션 구조로 사실상 합의 임박, 톤다운 코멘트 있으나 실행 단계 진입. / [2026-08-03] 경쟁 축 캐비앗: 뉴캐슬은 감독 공백으로 집행력 부재 · 자금은 증가 가능 — 두 방향이 상쇄돼 순효과는 미확정.','팔리냐','2026-08-09');
INSERT INTO transfer_targets VALUES(95,'AVL','2026-summer','João Gomes','주앙 고메스',1015267,'Wolverhampton','DM/CM','LDM','CONFIRMED','11111551335X5443756411211',47.0,47.10000000000000142,6,6.650000000000000355,'dm_dlp','Roaming','dm_dlp','Roaming',0.7890000000000000346,unistr('틸레만스 대체 영입 — 클럽간 합의(초기 £34.6m+애드온 £4.3m, 총 ~£38m), 금주 메디컬 예정. 아틀레티코행이 멘데스-구단 갈등으로 결렬된 것을 빌라가 인터셉트. [2026-07-17 실측+3축] 최근 6경기(45분+): 태클 3.7·듀얼 7.0·kp .3·xA .04 — 기능=순수 볼위너+박투박 엔진(카마라형). 움직임 최근접 dlp/Roaming .797(LDM — 우측 배치 .638로 좌측 우세). 기능축 우선(obs#31)으로 처방 dm_holding/Ball-Winning. [2026-07-18 재확인] 메디컬 금요일(7/17) 진행 — 포르투갈 캠프 이탈·귀국 확인, 개인조건 2031년 계약 합의(Schira). 공식 발표 임박. [2026-07-28 FC26 통합 확인] 기능축 우선 처방(dm_holding/Ball-Winning) 유지. 캐비앗: FC26 숙련은 boxcrasher/widehalf/dlp/cm_dlp — holding 마커 없음. 압박검증·슬라이딩태클 PS는 볼위닝 기능 지지. [2026-07-29 홀딩 처방 재검증 — 유지 확정] 현행 커널 재검산: dlp/Roaming .797 정확 재현(stale 아님), holding/Ball-Winning은 .45로 움직임 불일치. 그러나 ①실측 홀딩 동료와 직접 유사 — 온아나 그리드 .835/카마라 .805 (둘 다 움직임 코사인은 dlp .87이었으나 기능축으로 holding 처방된 동일 패턴, obs#32) ②기능=창조 전무(kp .3·xA .04) — dlp 지시는 전개 산출 없는 선수에게 공급 책임 부여하는 모순 ③요구역할=카마라 장기부상 중 앵커 대체+obs#27 블록 전제. 3축 모두 holding 지지 → dm_holding/Ball-Winning 유지. 숙련 캐비앗 대응: holding 미숙련 페널티 확인 시 차선은 dm_boxcrasher/Balanced(.701, 숙련 보유+박투박 기능 부합)이며 dlp가 아님. left-release-A 프리셋의 LDM dlp 공급 요건은 고메스 기능으로 충족 불가 — 진성 DLP형(사라·베르그발) 영입 또는 boxcrasher 절충 필요.\u000a\u000a[2026-07-31 H안] 프리셋 LDM 선발로 승격되며 처방을 dm_holding/Ball-Winning → **dm_dlp/Roaming .789**(숙련✓)로 교체. 커널 교체로 만잠비(.726)와 순위가 역전됐다(이전 만잠비 .812 > 고메스 .797). ⚠️ 캐비앗: 고메스도 기능상 볼위너이고(창조 kp .3·xA .04) 스쿼드에 진성 DLP가 없다 — 적합을 위해 기능 정합을 포기한 칸이다. [2026-08-05 역할 처방 확정 — 기존 dm_dlp/Roaming 유지] LDM(x=38) 전수 채점: dm_dlp/Roaming 0.789 → dm_dlp/Build-Up 0.714(Δ.075) → dm_boxcrasher/Balanced 0.685 → dm_holding/Roaming 0.669(Δ.120) → dm_dlp/Defend 0.578 → … → dm_holding/Ball-Winning 0.452(9/10). RDM에서는 0.680으로 LDM보다 Δ.109 낮아 **좌측 배치 확정**. [기능축 충돌은 계승 — 명시적 지불] 툴 FUNC_AXIS가 고메스를 {role:dm_holding, mode:prefer}로 두고 why에 "창조 전무(kp .3 · xA .04)로 기능축은 볼위너. 다만 dm_dlp 적합이 뚜렷이 높아 프리셋은 dlp를 채택 — 적합을 위해 기능 정합을 포기한 칸"이라 적어뒀다. 2026-08-05 이벤트 측정이 그 근거를 **독립 재현**했다: 키패스 0.30/90(FUNC_AXIS의 kp .3과 정확히 일치). dm_holding/Roaming으로 돌리면 .789→.669로 Δ.120 손실이고 동점 임계(.03)의 4배라 타이브레이커 논리로 정당화되지 않는다 → dm_dlp/Roaming 유지. [카마라와의 3선 분담] 겹침 .715로 가용 피봇 조합 중 최저(고메스↔오나나 .874가 최고 중복, 카마라↔오나나 .814, 카마라↔바클리 .806, 고메스↔바클리 .753). 좌우는 열중심 고메스 46.8 vs 카마라 62.3, 깊이는 수비3rd 고메스 7% vs 카마라 11~15%. **기능 분담은 역할 이름이 아니라 슬롯+선수 능력치가 만든다** — 이벤트 per-90: 고메스 태클 3.52 vs 카마라 2.33 / 카마라 패스 52.5 vs 42.5 · 키패스 0.93 vs 0.30 · 인터셉트 1.40 vs 0.70 · 롱볼 정확도 62.5% vs 44.0%. 즉 카마라 배급·읽기, 고메스 압박·차단. ⚠️ 표본 교란: 카마라는 25-11~26-01 빌라(4위권), 고메스는 26-02~05 울브스 — 약팀 미드필더는 구조적으로 패스가 적고 태클이 많아 교란 방향이 관측과 일치한다. 비율 지표(롱볼 정확도 18.5pp 차·키패스 3.1배)가 더 신뢰된다. ⚠️ 불변규칙 7 — 이 실측은 울브스 체제 표본이므로 개인 위치 성향 기준선으로만 쓰고 에메리 3선 구조의 근거로 쓰지 않는다. 빌라 소속 공식전 표본은 0경기다(프리시즌 5경기는 SofaScore 선수별 데이터 전건 404).'),'ESPN(1티어, sources) fee agreed ~€40m ; Fabrizio Romano(1티어) "here we go" £34.6m+£4.3m (2026-07-16~17) ; SofaScore API player 1015267 (2026-07-17, 최근 6경기 45분+)','CONFIRMED — 1티어 이중 확인(ESPN+Romano here we go), 메디컬만 남음(만잠비·틸레만스 선례와 동일 단계). 실측 HIGH(6경기 전부 45분+). / 2026-07-18: 메디컬 진행 — 발표만 대기.','고메스',NULL);
INSERT INTO transfer_targets VALUES(121,'AVL','2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg → Aston Villa','CM/AM','CAM','CONFIRMED','25012X7564332351311200020',46.46999999999999887,61.39000000000000056,4,7.480000000000000426,'cam_halfwinger','Balanced','cam_halfwinger','Balanced',0.8169999999999999484,'합류확정 멀티포지션 부여: 스위스 대표팀 전진 배치 실측 — 월드컵 2경기(캐나다 8.1·알제리 7.8)+친선 2경기(호주·요르단, lineup pos=F) 통합 4경기 168pt, 중심 tool(46.5,61.4). CAM 배치 cam_halfwinger/Balanced 0.817 — 클럽(프라이부르크) 딥롤 그리드의 CAM 적합(0.575)과 달리 대표팀 전진 표본에서 10번 적합 뚜렷. 월드컵 3골(8강 진출)이 이 전진 롤에서 나옴 — 클럽 box-to-box와 별개로 세컨드 스트라이커/10번 활용 여지 실증.','SofaScore API player 1518931 — events 12813019/15186821(WC)/16118856/15891673(친선) (수집 2026-07-21)','CONFIRMED(합류) — 실측 신뢰 MEDIUM: 대표팀 표본 4경기(친선 2 포함) 168pt, 클럽 CAM 순수 표본 없음. 스위스가 실제로 전진 배치해 검증된 롤.','만잠비',NULL);
INSERT INTO transfer_targets VALUES(122,'AVL','2026-summer','Johan Manzambi','만잠비',1518931,'SC Freiburg → Aston Villa','CM/AM','LM','CONFIRMED','25012X7564332351311200020',46.46999999999999887,61.39000000000000056,4,7.480000000000000426,'wm_insidefwd','Balanced','wm_insidefwd','Balanced',0.6460000000000000186,'합류확정 멀티포지션 부여: LM 순수 출전 표본 없음 — 대표팀 전진 그리드(4경기 168pt)의 LM 슬롯 재배치 적합 0.700(wm_insidefwd/Balanced), 클럽 그리드 기준은 0.607. 좌 하프스페이스 커버는 가능하나 터치라인 고정형이 아닌 중앙 회귀 성향 — 로테이션/변형 옵션 등급.','SofaScore API player 1518931 — 대표팀 4경기 통합 그리드 슬롯 재배치 계산 (수집 2026-07-21)','CONFIRMED(합류) — 실측 신뢰 LOW-MEDIUM: LM 포지션 순수 표본 부재, 전진 그리드의 재배치 적합 계산치.','만잠비',NULL);
INSERT INTO transfer_targets VALUES(123,'AVL','2026-summer','Nicolas Jackson',NULL,NULL,'Chelsea','ST','ST','HIGH (정체 — 07-28 이후 단계 전진 없음)','457725X496434211211100000',48.0,68.79999999999999716,6,7.450000000000000177,'st_advanced','Support','st_advanced','Support',0.7520000000000000017,'로저스 매각(첼시 £117m)으로 확보한 자금 재투자 대상, 에메리-비야레알 인연. [2026-07-24 갱신] 가르나초 CONFIRMED로 정리된 후에도 별개 딜로 논의 지속 확인 — 첼시가 £65m 요구가 명확히 설정(협상 기준가), 잭슨 본인도 정규 출전시간을 위해 빌라 이적에 열려있음("open to a move"). 로마노(1티어) "에메리 여전히 팬" + 양 구단 논의 지속 확인. 빌라 재정 제약으로 £60m 이하 필요 시사(협상 지속 근거) — 협상 단계 진입으로 등급 상향. [2026-07-27 21시 최신화] Sky Sports(1티어) 공식: 빌라가 조건 타진 중이며 "positive discussions" 진행. 첼시 호가 £60m+, 빌라는 클럽 레코드 경신 예상. 로저스·가르나초에 이은 첼시-빌라 세 번째 딜로 그림 완성. [2026-07-28 FC26 통합 확인] 실측 0.752 + 숙련 st_advanced+ 일치 — 확정. Support 포커스는 하강 링크 성향(실측)과 게임체인저/테크니컬 PS 부합. [2026-07-29 14시 재확인 — HIGH 유지] Plettenberg(7/28): 첼시·선수 측과 직접 협상 진행 중(영구 or 대여), 합의 아직 없음. 첼시 호가 £65m(영구 선호), 빌라 클럽레코드 경신 준비 보도(GMS). 호재: 첼시가 웰벡(브라이튼) 영입 검토 — 잭슨 방출 여지 확대. [경쟁구도 2026-07-30] 빌라 우위(단독) — 1티어가 협상 단계를 확인한 클럽은 빌라뿐이고 경쟁은 무명 "주시" 수준(CaughtOffside 3티어). 선수 선호는 상충(TEAMtalk 7/24 에메리 재결합 적극 vs The Sun 7/20 첼시 잔류 희망)이나 최신성 기준 7/27 Plettenberg 협상 진행 보도가 우세. 병목은 클럽 경쟁이 아니라 £65m 구단기록 + 왓킨스·에이브러햄 유출 선행. 날짜함정: "뉴캐슬 preliminary contact £80m"은 2025-07-28 기사로 본 창과 무관. [2026-08-03 21시] 구조적 제약 확정 — PL 규정상 **같은 PL 클럽에서 한 시즌 임대는 1명까지**이고, 빌라는 이미 가르나초로 첼시 임대 쿼터를 소진했다(Football London·Ryan Taylor). 따라서 Plettenberg가 07-28에 남겨둔 "영구 or 대여" 양갈래에서 **대여 경로는 규정상 봉쇄**되고 완전이적만 남는다. 이는 "첼시가 완전이적 선호"라는 상대 의향을 **규정 차원의 강제**로 굳히는 것이라, 빌라가 £60m+ 자금을 실제로 마련하지 못하면 딜 자체가 성립하지 않는다. 단계 변화는 아니므로 HIGH 유지. [2026-08-05 심층 — HIGH 유지 + 정체 플래그] 등급 근거는 유효하나 08-01~05 사이 1티어발 진전이 0이다. 협상 단계를 확인한 마지막 1티어 보도는 07-28(Plettenberg/Romano)이고, 공식 오퍼·금액 합의·메디컬·here we go 전부 없다. 07-24 이후 12일간 단계 전진 증거 없음 → HIGH는 유지하되 정체 상태로 표기. ⑴ HIGH 지탱 근거 강화: 1티어 3개 축 독립 확인(Romano 07-20·07-28 / Ornstein·The Athletic 07-22 완전이적 시 4년 계약 골격 / Plettenberg 07-27~28 첼시·선수 측 직접 협상). 경쟁 전멸 — 바이에른은 €65m 매수옵션을 40경기 출전 조건 미달로 포기해 완전 소멸, 토트넘 참전설은 Daily Mail 08-04 보도 당일 스퍼스 전담 Alasdair Gold가 부정, 뉴캐슬 링크는 2025년 창 잔상이다. 사우디 링크는 0건. §2-1 판정 빌라 단독 우위. ⑵ 08월 신규 구조 변화 — 첼시가 08-01 대니 웰벡(브라이턴, 2년) 영입을 공식 발표해 ST/CF 자원이 8명이 됐다(조앙 페드로·웰벡·에메가·델랍·기우·잭슨·음훼카·사트파예프). 여기에 25/26 리그 10위로 유럽대항전 없음(상금·중계권 £80m+ 결손) + 26/27 SCR·SSR 신규 규정 + PL 25인 한도가 겹쳐 첼시는 반드시 판다. 잭슨 아니면 델랍이며 시장가는 잭슨이 훨씬 높다. ⑶ 상향(임박) 차단 요인: 첼시 £65m 고정 vs 빌라 "£60m 미만이어야"(Telegraph)로 £5m+ 격차 미해소. 임대 경로는 Romano 07-28로 규정상 완전 봉쇄 확정(PL 동일구단 임대 1명, 가르나초가 소진) → £60m+ 일시 완전이적만 남았고 이는 07-17 만잠비 £59.5m 직후의 구단 기록 재경신을 뜻한다. Ben Jacobs가 언급한 "£10m 임대료+조건부 의무매입" 안은 이 규정과 충돌해 성립 불가. ⑷ 양방향 교착 — Tanswell(The Athletic 07-28): 빌라는 왓킨스·에이브러햄 중 누가 나갈 경우에 대비해 대안을 평가 중이지 능동적으로 밀어내지 않는다 / TEAMtalk 07-24: 잭슨이 와야 빌라가 왓킨스 이적에 열린 자세가 된다. 그런데 왓킨스 맨유행은 08-04 기준 냉각(맨유가 Sesko 보유, 지르크지 매각 선행 필요) → 교착 해소 트리거가 사라졌다. ⑸ Sky Sports(Dharmesh Sheth, 07-28)가 "빌라가 이 영입을 피할 수도 있는 이유" 영상을 자체 방송 — 1티어 매체의 명시적 회의론. [배치 서사 vs 실측 2026-08-05 — 불변규칙 3] 복수 보도가 "천성은 ST지만 에메리 팀에서는 주로 측면(좌측)에서 뛸 것"이라 예상하나, 실측 그리드를 슬롯별로 채점하면 ST(x=50) st_advanced/Support .752 > CAM(x=50) cam_playmaker/Roaming .742 > LM(x=14) wm_insidefwd/Balanced .667 > RM(x=85) .661이다. 좌측 배치 서사는 실측이 지지하지 않는다(LM이 ST보다 .085 낮음). 다만 ST와 CAM이 Δ.010으로 사실상 동률이라는 것이 새 사실 — 상위 2대역(공격3rd 32%+공격미들 43%)에 75%가 몰린 높은 원톱이면서 CAM 대역을 함께 점유한다. 좌우 편향은 좌 43%/중앙 20%/우 37%로 중앙형이며 뚜렷한 좌측 드리프트는 관측되지 않는다. [ST 슬롯 상대 평가] 잭슨 .752(Δ.115)는 현 주전 왓킨스의 25/26 시즌 그리드 .722(Δ.032, 동점구간)보다 높고 역할 정체성도 선명하다. 단 잭슨↔왓킨스 코사인 .911로 같은 구역을 쓰는 대체재이지 보완재가 아니다 — 병행 기용 시 ST 슬롯이 중복된다. 높이 차이: 잭슨은 상위 2대역 75%·수비3rd 0%로 내려오지 않고, 왓킨스는 64%·수비미들 13%로 더 넓게 움직인다. [2026-08-08 09시 재확인] 빌라가 £65m 정식 오퍼를 검토 중이라는 서술 확인(Romano 재확인) — 가르나초 임대 슬롯 소진으로 잭슨은 완전이적만 가능. 토트넘 경쟁 유지. 관심→검토 수준, 단계 진전 아님. HIGH(정체) 유지. [2026-08-09 최신화 — HIGH(정체) 유지] The Athletic이 첼시 호가를 £65m으로 확정 보도, 성사 시 빌라 클럽 레코드. Telegraph는 빌라가 재정 제약상 £60m 미만을 필요로 한다고 보도 — £5m 갭이 병목. Plettenberg(Sky DE): 빌라가 첼시·선수 측 양쪽과 direct talks 중이나 어느 쪽도 합의 없음. 선수는 이적에 매우 개방적이나 출전 보장을 요구. ⚠️ 신규 구조 사실: **임대는 이번 여름 불가능**(TribalFootball) — 가르나초 임대로 PL 동일구단 임대 슬롯이 소진돼 완전이적만 남았고, 총액 부담이 고정됐다. 첼시는 강제 매각 의사는 없으나 £65m 충족 시 승인. 첼시 depth: 조앙 페드로가 주전 9번, 로저스가 좌측 공격 예정이라 잭슨의 출전 전망은 낮다(매각 동기 존재). 단계 전진은 여전히 없음 — 공식 오퍼 제출 보도 0건. ⭐⭐[2026-08-10 21시 — 신규 구조 제약 발견] **UEFA 45일 스왑 규정**: 모건 로저스 이적(첼시행)으로부터 **45일 이내에 첼시→빌라 추가 거래가 성사되면 UEFA가 이를 스왑 딜로 분류**한다. 스왑으로 분류되면 양 구단의 순이익 인식이 제한돼 **빌라의 PSR 이득이 사라진다** — 로저스 £117m을 순수입으로 계상하려는 빌라에게 치명적이다. ⇒ **£5m 호가 갭보다 이쪽이 더 근본적인 병목일 수 있다.** 가르나초 임대로 PL 동일구단 임대 슬롯이 이미 소진된 것(완전이적만 가능)과 **별개의 제약**이며 둘이 겹친다. ⚠️ 로저스 이적일 기준 45일이 이적창 마감(2026-09-01 23:00 BST)을 넘길 개연성이 있어 **창 내 성사 가능성 자체를 낮춘다** — 정확한 기산일 확인이 다음 회차 최우선. 출처: Sky Sports 경유(발행일 미확정, 등급 근거 아닌 구조 정보로 기록). ⭐⭐[2026-08-10 심야 — 45일 규정 정밀화, 어제 서술 완화] **모건 로저스 첼시 공식 발표일이 2026-07-22로 확정됐다**(Sky Sports 기사 본문 타임스탬프 "Wednesday 22 July 2026 10:46 UK", 1티어 직접 확인 · Al Jazeera 독립 확인). ⇒ **45일 만료 = 2026-09-05**로, 창 마감(09-01 23:00 BST)보다 **4일 늦다.** 즉 **잔여 창 전체가 45일 구간 안에 있다.** ⚠️ 이는 Ben Jacobs(2티어, 08-08)의 "빌라가 45일 회피를 위해 창 막판까지 의도적으로 지연할 수 있다"는 서술과 충돌한다 — 영구이적 기준으로는 창 안에서 45일을 벗어날 방법이 없다. ⚠️⚠️ **그러나 규정 원문 확인 결과 어제의 "구조적 병목" 프레이밍은 한 단계 완화해야 한다**: UEFA **Annex G.3.5**는 (a) 45일 이내 체결 **AND** (b) 동일·유사한 지급 의무·기한일 때 교환으로 보는 **연언 조건**이고, 판정은 **substance over form**이라 45일은 **자동 판정선이 아니다**(45일 밖에서도 스왑 판정된 선례 존재: 토트넘·브라이턴 van Hecke·Vuskovic). ⇒ **45일은 하드 게이트가 아니라 추정 인자다.** 실제 회피 경로는 (a)가 아니라 **(b) 지급 구조**이며 그 실증이 **가르나초**다(시즌 임대 + 다음 시즌 발동 의무조항으로 "구간 밖" 인정, 로저스 순이익 약 £93m 보존). ★ **그런데 잭슨에게는 그 (b) 경로가 막혀 있다** — 가르나초 임대로 **PL 동일구단 임대 슬롯이 소진**돼 완전이적만 가능하다. **가르나초가 쓴 탈출구를 가르나초가 닫았다.** 단계는 불변 — 첼시 호가 £65m(The Athletic·BBC), 빌라는 "공식 입찰 검토 중", **공식 오퍼 제출 0건**. Football London: 첼시는 £65m이 오면 막지 않으나 밀어내지도 않는다.','Fabrizio Romano(1티어) 관심·에메리 각별 신뢰 확인 ; Football Insider(2티어) £60-65m 요구 ; Yahoo Sports "step up talks" ; SofaScore API player 1085381 (2026-07-21) ; thehardtackle(2026-07-19,21) 논의/가격 설정 ; Yahoo Sports(잭슨 open to move) ; teamtalk(2클럽 논의 중) ; Romano X 2079473534951211218 ; teamtalk nicolas-jackson-villa-break-transfer-record (재검증 07-26); Sky Sports; BBC(gossip); TeamTalk; Africasoccer ; [08-05 심층] Ornstein/The Athletic(1티어) 2026-07-22 4년 계약 골격 via https://uk.sports.yahoo.com/news/why-aston-villa-sign-nicolas-180000917.html ; Plettenberg/Sky Germany 2026-07-28 https://www.caughtoffside.com/2026/07/28/aston-villa-nicolas-jackson-transfer-florian-plettenberg/ ; Romano 2026-07-28 임대 불가 확정 https://www.givemesport.com/aston-villa-nicolas-jackson-chelsea-transfer-romano-update/ ; Sky Sports(Sheth) 회의론 영상 2026-07-28 https://www.skysports.com/football/video/12606/13567768/nicolas-jackson-why-aston-villa-may-avoid-signing-striker-from-chelsea ; 웰벡 첼시 이적 2026-08-01 https://www.espn.com/soccer/story/_/id/49478554/danny-welbeck-chelsea-brighton-premier-league-transfers ; BBC 알론소 발언 2026-08-04 ; Daily Mail(Rosser) 2026-08-04 스퍼스 참전 → 당일 football.london 부정 https://www.sportsmole.co.uk/football/spurs/transfer-talk/news/nico-or-nic-no-jackson-to-tottenham-transfer-truth-revealed_602396.html','HIGH 유지 — 1티어(Sky) 협상 진행 확인, 기록적 이적료 임박 분위기. [2026-08-03 21시] 임대 경로 봉쇄는 규정 근거(PL 동일구단 임대 1명)라 보도 티어와 무관하게 성립 — 단, 가르나초 딜이 임대 구조라는 전제에 의존한다(현재 조건부 임대+£40m 완전이적 옵션으로 보도됨). [2026-08-05 심층 추가] ⓐ ⚠️ 실측 출처 미확정(검증 백로그) — source의 "SofaScore API player 1085381 (2026-07-21)" 6경기 표본이 어느 대회 것인지 DB에 기록돼 있지 않다. 잭슨은 25/26 시즌 전체를 바이에른 뮌헨 임대로 보냈고(2025-09-01~2026-06-30) 2026 월드컵에 세네갈 대표로 출전했다. 따라서 2026-07-21 기준 "최근 6경기"는 바이에른 25/26 경기·월드컵 경기·혼재 중 어느 것도 가능하다. club 필드의 "Chelsea"는 소속 구단이지 측정 출처가 아니다. 월드컵 표본이 섞였다면 클럽 전술 맥락과 다른 데이터이므로 재수집이 필요하다. → 다음 SofaScore 접근 시 event id 목록을 확인해 rationale에 명기할 것. ⓑ 선수 의사 상충 — TEAMtalk(Graeme Bailey) 07-24 "에메리 재회에 매우 열려 있고 완전이적을 원한다" vs The Sun 07월 "첼시에 남아 알론소 밑에서 증명하기로 결심" vs Daily Mail(Jack Rosser) 08-04 "보장된 출전시간을 찾아 떠날 준비". 본인 직접 발언 원문은 이번 창에 확보되지 않았다(DSPORTS "나는 첼시 선수다"는 2025년 창 발언). 공통분모는 "출전시간 보장 요구"이며, 바이에른에서 전 대회 선발 15경기에 그친 경험이 결정 변수다 — 빌라가 왓킨스 위 서열을 보장하지 못하면 본인 동의가 흔들릴 수 있다. ⓒ 알론소 08-04 홍콩 기자회견(BBC, 1티어)은 중립~잔류 톤 — "니코는 훌륭한 선수", "함께 있어 기쁘다", "하루하루 옵션을 점검하겠다", "시장은 아직 3주 남았다". 매각 확정 뉘앙스가 아니다. 알론소는 전통적으로 장신 타깃형 9번을 선호해 조앙 페드로·에메가가 그 틀에 더 맞는다는 분석이 병기된다. ⓓ 계약이 2033년까지라 레버리지는 전적으로 첼시에 있다 — 급히 팔 이유가 없다는 점이 £65m 고정 호가를 지탱한다. ⓔ 부상 이력(Transfermarkt): 25/26 무부상, 24/25 햄스트링 58일(10경기), 23/24 발목 56일, 22/23 고관절 57일(15경기), 20/21 근섬유 파열. 누적 결장은 적으나 "한 시즌 1회 8주급" 근육·관절 패턴이 반복된다. 2026 월드컵 + 2025 AFCON 참가로 여름 부하 누적이 리스크. ⓕ ⚠️ §2-0 휴리스틱 실패 사례 기록 — 이 건에서는 "나이 표기로 재순환 기사를 거른다"는 규칙이 오탐을 낸다. 2026년 창에 실제 발행된 기사들이 잭슨 나이를 제각각 틀리게 적었다(TEAMtalk 07-24 "25" 정확 / GiveMeSport 07-24 "23" / Yahoo 07-20 "27" / Yahoo 08-04 "24"). 마지막 건은 "24세"로 쓰면서 본문에서 08-05 홍콩 유벤투스 친선전을 언급해 명백히 2026-08 발행이다. → 이 선수에 한해 대체 판별 지표를 쓸 것: 로저스 첼시 £117m · 가르나초 빌라 임대 · 만잠비 빌라 £59.5m(07-17) · 웰벡 첼시 이적(08-01) · 알론소가 현 감독이고 마레스카는 전 감독 · 첼시 25/26 리그 10위 유럽대항전 없음 · 맨유 감독 Michael Carrick · 바이에른이 매수옵션 포기(2025년 기사는 "관심 중" 단계). ⓖ 인용 금지: newsstation2.com 2026-08-01 "빌라-첼시 합의·메디컬 예정"은 콘텐츠 팜이며 1·2티어 교차확인 0건, 08-04 Daily Mail·BBC가 여전히 미해결로 서술해 사실상 반증됐다. BBC 가십 07-29 "첼시가 로저스 대가로 Tosin+잭슨+현금 제안"은 로저스 딜이 07-20경 이미 합의된 것과 시간순 모순이라 근거로 쓰지 말 것.','잭슨','2026-08-09');
INSERT INTO transfer_targets VALUES(129,'AVL','2026-summer','Alejandro Garnacho',NULL,NULL,'Chelsea','LW','LM','CONFIRMED','88210X4101720004100011000',22.30000000000000071,66.5,6,7.030000000000000248,'wm_winger','Attack','wm_winger','Attack',0.8040000000000000479,unistr('첼시 초기 로그론 + 의무구매옵션(사실상 확정), 4년 계약. Romano "here we go" + Ornstein 메디컬 완료 확인 (2026-07-22/23). [2026-07-28 FC26 통합 확인] 실측 0.911 + 숙련 wm_insidefwd+ 일치 + PAC86/감아차기 — 처방 확정.\u000a\u000a[2026-07-31 obs#94 커널 교체 + H안 재설계] 처방을 wm_insidefwd/Attack → **wm_winger/Attack .804**(숙련✓)로 교체. 옛 placedMap이 인사이드 포워드 커널을 터치라인(x=14)으로 시프트해 적합을 .911로 부풀리고 있었고, EA 정본 변형으로는 .671이다. 실측에 맞는 것은 winger 계열이며 좌측 해방의 성격이 컷인 → 터치라인 침투로 바뀐다. 뱅크는 0.00 유지라 C1(두 줄 4) 무사.'),'https://sports.yahoo.com/articles/aston-villa-agree-deal-sign-170000479.html','HIGH — 1티어(Romano exclusive, Ornstein medical) 확인','가르나초',NULL);
INSERT INTO transfer_targets VALUES(135,'AVL','2026-summer','Emerson Royal','에메르송 호이알',856123,'Flamengo','RB','RB','MEDIUM-HIGH','000250002X000150002600012',86.20000000000000284,56.70000000000000284,6,6.879999999999999894,'fb_att_wb','Support','fb_att_wb','Support',0.949999999999999956,'Matty Cash 백업 필요(안드레스 가르시아 게타페 임대行) — Villa가 Flamengo에 €9m 공식 제안 제출(6/23), Flamengo 거부 후에도 재제안 검토 중. Sky Sports Paper Talk(출처: The Athletic)가 협상 사실 보도, 선수 본인도 공개적으로 제안 수령 확인. 아직 합의 단계 아님(Flamengo 계약 2028까지, 판매 거부 기조) → MEDIUM-HIGH(1티어 협상 보도, 합의 전). [2026-07-29 14시 재확인 — 유지] 디테일 진전: 블록 주체=자르딤 감독(ESPN Brazil Andrade — "회장단은 승인 의향, 감독이 중단"). €9m→€10m 증액 제안도 보류됨. 선수는 공개적으로 긍정 반응, 협상 재개 여지 유효. [2026-07-30 실측 완료] 툴중심(86.2,56.7)=우측 전용. RB 커널 적합 fb_att_wb/Support 0.950 > fb_inverted/Attack 0.923 — 캐시 실측의 동일역할 적합(0.898)을 상회. 전방2행/자기진영2행 질량비 0.53/0.31 vs 캐시 0.33/0.47 → 캐시보다 뚜렷한 전진형 풀백(공격 관여 +0.20, 수비 커버 -0.16). 함의: C(우측 침투) 프리셋의 RB 처방 fb_att_wb/Support에 캐시보다 정합적이나, 자기진영 질량 하락이 이미 라인 48로 내린 C의 수비 리스크를 더한다 — 프리셋 채택은 별도 판단. [경쟁구도 2026-07-30] 빌라 단독 우위(경쟁 클럽 0건) — 오퍼를 낸 유일한 클럽이고 선수도 공개 호응("이 제안을 받아 매우 기쁘다"). 장애물은 경쟁이 아니라 플라멩구의 스쿼드 판단: Casagrande(플라멩구 전담) — 지금 팔면 자르딤이 바렐라의 즉시 대체자를 잃는다는 이유이며 금전 문제가 아니다(빌라는 이미 호가 충족, 결렬이 아니라 냉각). 상향 트리거 = 플라멩구의 우측 백업 확보(에스투피냔-밀란 블록과 동일 패턴). [2026-08-09 재확인 — MEDIUM-HIGH 유지, 신규 근거 0건] 오늘 검색에서도 최신 보도가 6월말~7월 수준(플라멩구가 스쿼드 뎁스 우려로 €10m 오퍼 거부, 매각 자체를 보류)에 머물러 있다. 선수 본인은 "제안을 받아 기쁘다, 미래는 모른다"로 문을 열어둔 상태 유지. ⚠️ **last_news_date 2026-07-28 기준 STALE 시한(14일)은 2026-08-11** — 08-09 현재 12일 경과, 2일 남았다. 다음 회차(21시)~08-11에 신규 보도가 없으면 §4-3에 따라 DEAD(STALE) 전환 대상이다. 재확인 날짜를 last_news_date로 쓰지 않는다(§4-3 함정 규칙). [2026-08-10 심야 — STALE 전환 근거 확정] 전용 검색 2회로 **08-01 이후 빌라 링크 신규 보도가 0건**임을 확인했다(오늘 검색에 걸린 전건이 6월말~7월 빈티지의 재순환). 확인된 최신 실보도 타임라인: 2026-06-23 €9m 오퍼(ESPN Brasil) → €10m 인상(Venê Casagrande) → **플라멩구가 RB 뎁스 우려로 매각 철회**(재정 사유 아님 명시 — Varela와의 경쟁 필요) → 7월말 Bruno Lemos "빌라는 플라멩구의 대체자 확보를 기다리는 중". 선수 본인 발언(Itatiaia Esporte)도 7월 것이다. 계약 2028 + 1년 옵션. ⇒ `last_news_date` 2026-07-28 기준 오늘 **13일**. **08-11 시한 도달 시 §4-3 전환 근거가 성립한다**(신규 근거 0건 확인 완료).','Sky Sports(via The Athletic) 2026-07; Yahoo Sports/Sports Mole 2026-07','실측 6경기(45분+·히트포인트 62~107): FLA-SPA 90''7.1 / CHA-FLA 90''6.7 / FLA-COR 90''7.1 / FLA-CUS 90''7.1(리베르타도레스) / FLA-ELP 90''6.7(리베르타도레스) / VIT-FLA 90''6.6(코파) — 2026-05-15~07-26, 평균 6.88. 캐비앗: ① 브라질 리그·남미 대회 표본(리그 강도 보정 없음, 시세 LASK 사례와 동일 한계) ② 프리시즌 친선 4경기는 표본 제외 ③ INT-FLA(26'')·CAP-FLA(8'')·GRE-FLA(25'')은 45분 미달로 제외. 측정: claude-in-chrome, SofaScore API event/{eid}/player/{pid}/heatmap.','에메르송','2026-07-28');
INSERT INTO transfer_targets VALUES(139,'AVL','2026-summer','Allan','아우안',1835889,'Palmeiras','RW/CAM','RM','MEDIUM-HIGH','001361125X001360013500001',77.20000000000000284,59.39999999999999858,6,7.179999999999999716,'wm_winger','Balanced','wm_winger','Balanced',0.8120000000000000551,'로저스(첼시 £117m) 대체 창조 자원. 빌라가 €25m+옵션 €5m(총 €30m)·5년(+1년 옵션) 공식 입찰 → 팔메이라스 거절. SD Anderson Barros가 대리인에게 "협상 의사 없음" 직접 통보, 요구선 €45m 초과(나폴리 €35m·뉴캐슬·제니트 기거절). 계약 2029로 셀링클럽이 협상력 우위. [경쟁구도 2026-08-01] 단계는 빌라가 최선두(유일한 실제 입찰) — 뉴캐슬·리버풀은 관심 단계 보도뿐. 판정 **빌라 우위**이나 병목은 경쟁 클럽이 아니라 **셀링클럽 블록**이다. 등급 유지(HIGH는 협상 단계 요건 미충족 — 상대가 협상 자체를 거부). [실측 2026-08-01] SofaScore 히트맵 6경기(45분+·히트포인트 15+, 2026-05-05~07-30, 전부 팔메이라스) 균등가중 그리드. 중심 툴좌표 (77.2, 59.4) = **우측·전진** 편향이 뚜렷하고 평균 평점 **7.18**(최고 8.4). RM 슬롯(x=85) 커널 적합 **wm_winger/Balanced .812** — 기존 RM 후보 하지무사 .821·은디아예 .825와 **동급**이고 둘 다 DEAD인 지금 RM 슬롯의 유일한 실측 보유 후보다. ⚠️ W군(순수 윙어)으로 재면 w_wideplm/Build-Up .870으로 더 높다 = **뱅크(WM) 역할보다 해방 윙어에 가까운 풋프린트**이며, 에메리 우측이 요구하는 4-4-2 복귀(obs#27)와는 그만큼 어긋난다. CAM으로 재면 .674로 급락 → 등재 슬롯은 RM이 맞다. [2026-08-01 처방] opt=fit=wm_winger/Balanced(.812) — 타 영입 후보와 같은 규약(실측 argmax를 처방으로). ⚠️ 현 구조에서 RM은 두 줄 4의 **뱅크 칸**이라(obs#124) 실제 기용 시 wm_widemid/Support **.734**를 지불하게 된다(−.078). 즉 아우안은 해방 사이드용 자원이고, 좌측이 이미 해방으로 우세한 현 스쿼드에서는 구조적으로 어긋난다. [2026-08-02] ESPN Brasil(Bruno Andrade): 빌라는 **포기하지 않았고 2차 입찰을 준비 중**이다 — 다만 **아직 제출 전**이라 단계 변화는 없다(등급 유지). 팔메이라스가 협상 자체를 거부 중이라 이번 창 내 성사는 회의적이고, 브라질 시즌 종료 후 1월 재평가가 현실적이라는 관측이 병기된다. [2026-08-03] 셀링클럽 구조 제약 확인 — 팔메이라스는 Allan 경제권 70%를 보유하고 **국외 이적 바이아웃 €100m(R$630m)** 이 걸려 있다. ⚠️ 이 조항은 빌라 관심에 대한 신설 대응이 아니라 **2024-11 재계약 때부터 존재하던 상수**다(ESPN Brasil, 최초 보도 2025-02-25 — 당시 2027 만료·€100m, 이후 2029로 연장). 즉 €45m+ 요구선과 €100m 조항은 별개 층이며, 협상 결렬 시 빌라가 넘어야 할 실제 천장은 후자다. 추가로 아벨 페레이라가 기자회견에서 "협상이 이뤄진다면 주변부 선수에 한한다"고 직접 발언(1차 출처=공개 회견). ⚠️ **2030까지 재연장+조항 증액 협상 중**이라는 서술은 thefootball.com.br(3티어, 기자 미표기) 단독이라 채택하지 않는다 — ESPN 기사에는 해당 내용이 없다. [2026-08-09 최신화 — MEDIUM-HIGH 유지, 셀링클럽 블록 확인] ⚠️ 소속팀은 팔메이라스다(플라멩구 아님 — 플라멩구의 Allan은 동명이인 Allan Rodrigues, 현재 코린치안스 임대). ESPN(sources 기반): **빌라의 €30m 오퍼를 팔메이라스가 거부**했고 €45m 수준으로의 인상을 요구. 오퍼 구조는 고정 €25m + 보너스 €5m + 5년 계약(+1년 옵션). TeamTalk: 팔메이라스 회장 Leila Pereira와 감독 Abel Ferreira가 매각에 반대하며 "최근 아카데미 최고 재능, 가치가 계속 오를 선수"로 판단 — 빌라의 오퍼에 감사를 표하되 **비매품 통보**. [등급 판단] §2-1 보정표상 이는 "경쟁 클럽 우위"가 아니라 **셀링클럽 기조(잔류·호가)** 사유다. 빌라는 관심이 아니라 **실제 공식 오퍼를 제출한 단계**이고 2차 입찰도 배제되지 않았으므로 MEDIUM-HIGH 유지 — 다만 €15m 갭과 구단 수뇌부의 공개 반대가 병목이다. 선수: 22세, 2026시즌 6골 4도움, 통산 88경기 16공격P. 리버풀·뉴캐슬도 링크.','ESPN(1티어, Adriana Garcia 기명, sources 표기, 2026-07-29) https://www.espn.com/soccer/story/_/id/49478318/aston-villa-premier-leauge-allan-brazilian-serie-30-million-offer-rejected-sources ; 최초 정보 André Hernan(BR) ; TEAMtalk','MEDIUM-HIGH — 1티어가 **실제 제출된 입찰**을 확인(단순 관심 아님). 실측 완료(2026-08-01) — 6경기 균등가중, 인코딩 규약은 맥긴 14023928 회귀 검증(44포인트·25셀 완전 일치)으로 확인. ⚠️ 표본이 전부 **브라질 세리에A**라 리그 수준 보정 없음. ⚠️ 적합 .812는 슬롯 유형 WM 제한 하의 argmax이고, 무제한이면 W군이 더 높다(위 캐비앗). [2026-08-03] €100m 바이아웃은 ESPN Brasil로 교차 확인됨(신설 아님·상수). 2030 재연장설은 미채택(3티어 단독).','아우안','2026-08-09');
INSERT INTO transfer_targets VALUES(141,'AVL','2026-summer','Matteo Ruggeri','마테오 루헤리',965011,'Atlético Madrid','LB','LB','HIGH','32100X2000410007200031000',13.59999999999999965,47.20000000000000284,6,6.769999999999999574,NULL,NULL,'fb_att_wb','Support',0.948999999999999955,'좌측 풀백 — 아틀레티코가 그리말도(레버쿠젠, ~€20m) 영입 후 방출 대상으로 분류, 시메오네 구상 외. 빌라는 디뉴(→PSG 확정) 공백 + 에스투피냔 딜의 밀란 승인 정체가 겹쳐 즉시 영입 가능한 대안으로 선회 — Marca/Moretto는 ''빌라가 오퍼 제출, 선수가 검토 중, 몇 시간 내 결정 가능''으로 보도. 이적료 €20m 내외(아틀레티코 매입가 €17m+보너스 €3m 대비 차익). 선수 측(대리인 Tullio Tinti)이 아틀레티코 훈련장 방문, 본인은 화요일 훈련 제외. [경쟁구도 2026-08-04] 빌라 우위 — 유벤투스·로마 링크가 병기되지만 Moretto는 두 팀을 ''진짜 관심 아님''으로 선을 그었고 피오렌티나 링크는 2주 전 것이다. 현재 실제 오퍼를 낸 클럽은 빌라뿐 → §2-1 ''빌라 우위·단독''으로 등급 유지(상향은 1티어 협상/합의 보도 시). [실측 2026-08-04] SofaScore 965011, 최근 6경기(45분+·히트포인트 15+ 충족: LaLiga 05-24·05-17·05-12·05-09, UCL 05-05·04-29 — 05-02 발렌시아전은 출전 기록 없어 제외, 프리시즌 친선 2경기도 제외). 경기당 정규화 후 균등가중. fc26-heatmap.html의 roleOptions(''LB'', map25)로 직접 채점(별도 구현 없음, 회귀검증: MAPS 37역할·st_false9 존재·에스투피냔 .946/에메르송 .950 재현 확인). 슬롯 LB(x=13) 기준 fb_att_wb/Support 0.949 — 2위 fb_att_wb/Attack 0.735 대비 Δ.214로 동점 구간 무관 단독 1위. 에스투피냔(.946)과 사실상 동급 프로필이라 대체재로 정확히 기능한다. [2026-08-05 재확인 — 등급 유지] Luca Cerchione(이탈리아 기자) "이미 합의 도달"(€18m+€3m) 보도가 재순환하나 Moretto의 "선수 개인 수락 여부 불투명" 판단과 상충 — 1티어(Romano) 확인 없음. 유벤투스·로마 경쟁 언급도 신규 근거 없이 재순환(기존 Moretto "진짜 관심 아님" 판단 유효). 신규 악화·개선 신호 없음. [2026-08-05 심층 — 등급 MEDIUM-HIGH 유지, 근거 기반 강화] ⑴ 1티어 2축이 독립적으로 확인됨: The Athletic(Jacob Tanswell, 빌라 전담 1티어) "빌라 관심 + 에메리가 원하는 LB physical profile에 부합, 총액 ~€25m" + Marca(Isaac Suárez) via Moretto. 08-04 기록의 "1티어 직접 확인 미발견"은 이로써 해소 — §2표의 MEDIUM-HIGH 요건(1티어 관심 보도)을 정면 충족한다. 단 1티어가 확인한 것은 관심·프로필 적합까지이고 "클럽간 합의"는 Cerchione 단독이라 HIGH(1티어 협상/합의) 미충족. ⑵ 서사가 아닌 물리적 신호 2일 연속: 08-03 선발조 제외(유스 Arnau Sola가 그 자리) + 대리인 Tinti·Montipo가 마드리드 훈련장서 단장 Alemany와 대면 회담, 08-04 실내 자전거로 팀훈련 관전(훈련 미참가). ⑶ 아틀레티코 매도 동기 구조적 검증: 그리말도(2026-06-28 발표)+Hjulmand+Kang-in Lee 지출로 수입 필요, 매입가 €17m 대비 차익 확실, 무엇보다 Hancko가 LB 커버 가능해 대체 영입이 불필요하다 — 팔 이유는 있고 안 팔 이유가 없다. ⑷ 경쟁 실체 없음(Moretto가 유베·로마 직접 부정, 피오렌티나는 7월 이후 진전 없음) → 선수가 기다려도 받을 대안 오퍼가 현재 없다. ⑸ 빌라 측 시간 제약: 디뉴 이탈로 LB가 마첸 1명, 08-12 UEFA 슈퍼컵 상대가 PSG. 에스투피냔 플랜A는 아모림에 막혀 실질 폐쇄. ⑹ 잔여 리스크: 선수 수락·개인조건 합의가 어떤 소스에도 없고("la llave la tiene el jugador"), 메디컬 기록 전무, Romano/Ornstein/Sky UK/BBC 부재. [실측 재검증 2026-08-05] roleOptions(LB,x=13) 재실행 — fb_att_wb/Support .949 재현, 2위 fb_att_wb/Attack .735로 Δ.214. LB 후보 4인 중 최대 마진(에스투피냔 Δ.178 / 디뉴 Δ.044 / 마첸 Δ.026=동점구간). 대역분해: 공격3rd 17%·공격미들 33%(피크)·미들 14%·수비미들 25%·수비3rd 11%. 상호 코사인 — 에스투피냔 .975(사실상 동일 프로필, 완전 등가 대체재) / 디뉴 .909 / 마첸 .929(기존 자원과 역할 미중복). [서사 vs 실측 충돌 판정 2026-08-05 — 불변규칙 3] Total Football Analysis 스카우트 리포트는 루헤리 시그니처를 "언더랩(상대 풀백-CB 사이 침투)"·"공격 지표 전반 평균 이하"로 규정하나, 이 리포트는 2025-07-24 발행분이고 데이터가 아탈란타 24/25(가스페리니 3-4-3 LWB) 기반이다. 아틀레티코 25/26 실측은 반대다 — 터치라인 열 75%/하프스페이스 22%/중앙 3%로 폭을 제공하는 오버랩형이며, 디뉴(col0 76%)와 사실상 동일한 너비 규율이고 안으로 접히는 마첸(col0 64%·col1 28%)과 명확히 구분된다. Marca의 25/26 서술("carreras de superposicion이 그의 인장")이 실측과 일치. → 에메리 모듈레이션 4축의 "디뉴 vs 마첸" 축에서 루헤리는 디뉴 자리(전진·폭 제공)에 들어가며, 마첸과 역할이 겹치지 않는다. 다만 디뉴가 공격3rd 22%까지 밀고 올라가는 최종선 유형이라면 루헤리는 공격미들 대역 중심이라 fb_att_wb/Support 커널(col0 3/10/6/6/3)에 디뉴(.886)보다 더 잘 맞는다. [2026-08-06 상향 MEDIUM-HIGH→HIGH] 구단 간 합의 도달 — Marca(2티어): 고정 €18m + 보너스 €6m(총 €24m), Rubén Uria(2티어 스페인): 총액 €25m 원칙 합의. Moretto(2티어 이탈리아): 남은 관문은 선수의 "definitive yes" 하나 — 개인조건·메디컬 미완. 루제리는 아틀레티코 한국 프리시즌 투어 명단에서 제외돼 이적을 검토 중. [경쟁구도] 리버풀·뉴캐슬·유벤투스·로마가 관심을 보였으나 구단 합의에 도달한 곳은 빌라뿐 — 빌라 우위. The Athletic(1티어)은 빌라의 좌풀백 후보군에 루제리를 포함해 보도(관심 단계). [2026-08-07 09시 재확인 — HIGH 유지, **1티어 근거 최초 확보**] "definitive yes"는 오늘까지 미발행이라 CONFIRMED 승격 불가. 그러나 실질 진전이 있다: **Jacob Tanswell(The Athletic 빌라 전담, 1티어)**이 1874 Podcast에서 **"이적료는 대체로 합의됐고 현재 개인조건을 마무리 중"**이라고 확인했다. 08-06까지 이 건의 근거는 Marca·Uria·Moretto(전부 2티어)뿐이었으므로 **처음으로 1티어가 붙은 것**이 오늘의 변화다(HIGH 등급의 근거 기반이 사후적으로 보강됨). ⚠️ **팟캐스트 발언 시점 확정 실패** → §2-0에 따라 `last_news_date` 갱신 근거로는 쓰지 않고 rationale에만 남긴다. 선수 성향에 대해 "빌라 제안 수락 쪽으로 기울었다"는 2티어 전언이 있으나 08-04 Marca의 "타 구단 제안을 기다릴지 저울질"과 톤이 반대라 확정 근거로 쓰지 않는다. [2026-08-08 09시 갱신] Fabrizio Romano 본인 트윗(1티어, status ID로 발행시각 2026-08-08 09:13 UTC 확정) — "Aston Villa and Atlético Madrid have agreed on €20m deal for Matteo Ruggeri. The Italian left back also gave green light to the move with contract terms now being negotiated. Few more steps needed then it could get done." 클럽간 합의 + 선수 개인 그린라이트 확보, 개인조건(계약) 협상 중 — 메디컬·공식발표 전 단계. ⚠️ 일부 WebSearch 요약이 "Here we go"를 인용했으나 원문 대조 결과 오염으로 판단, 폐기. HIGH 유지(CONFIRMED 미달). [2026-08-09 09시 재확인 — HIGH 유지] Moretto/Yahoo: 개인조건(계약) 아직 미합의이나 큰 저항은 없을 것으로 전망, 아틀레티코 한국 투어 명단 제외가 이적 임박 신호로 재확인. 메디컬은 합의 완료 시 "다음 주" 진행 전망. 이적료 구조는 매체별로 €18m+€6m(Marca) vs 총액 €25m(스페인 매체) 두 서술 병존 — 액수 자체는 불변, 단계도 불변(계약조건 협상 중). [2026-08-10 09시 갱신 — HIGH 유지] Moretto(2티어, 당일): 이적 임박·선수 개인조건 합의 방향 — 08-09 시점의 "개인조건 미합의"에서 한 단계 전진. Romano(1티어)는 €20m 클럽간 합의를 확인하면서도 "아직 상당한 이슈 하나가 남아 있다"고 유보를 병기 — 두 보도가 상충하지는 않으나 메디컬 일정·공식 발표는 여전히 미확인이라 CONFIRMED 요건 미달. 이적료 서술은 €18m+€6m(Marca) / 총액 €24~25m / €20m(Romano)로 매체별 병존, 액수 폭 불변. ⚠️[2026-08-10 자기정정] 이 회차의 갱신 내용은 **발행일 확정 실패**다 — Moretto 건은 TransferFeed "1h ago" 스탬프(수집 시각이지 발행 시각이 아님, §1)에만 근거하고 원문 날짜를 잡지 못했다. §2-0에 따라 last_news_date를 08-09로 되돌린다(STALE 시계는 확정된 보도일로만 움직인다). [2026-08-10 21시 갱신 — HIGH 유지] 신규 구체 사실: **Nicolò Schira — 개인조건 합의 완료, 계약 2031년까지**. 아틀레티코 한국 프리시즌 투어 제외 상태 유지, "최종 절차만 남았다"는 서술. **뉴캐슬·리버풀의 하이재킹 시도는 실패**했고 로마·유벤투스 관심도 무산 — §2-1상 빌라 단독 우위 확정. 여전히 **메디컬 완료·공식 발표 보도는 0건**이라 CONFIRMED 미달. ⚠️ 발행일 미확정이라 last_news_date는 08-09 유지(§4-3). [2026-08-10 심야 — HIGH 유지, 실질 전진 없음] **Romano(1티어) 원문 확보**: "Aston Villa and Atletico Madrid have agreed on €20m deal... The Italian left back also gave green light to the move with contract terms now being negotiated" + **"few more steps needed"**(08-08). Moretto도 "imminent"이나 **메디컬·계약 서명은 남아 있음**. Tanswell(The Athletic, 트윗 ID 2085983367137288667 → 스노우플레이크 역산 **2026-08-08 06:55 UTC**)은 **"클럽간 fee는 broadly agreed, 개인조건은 마무리 중"** — ⚠️ 21시 회차에 기록한 Schira의 "개인조건 합의 완료"와 **상충**하나 Schira 건은 발행일 미확정이라 선후를 가릴 수 없다. **메디컬·공식 발표 0건 유지 → CONFIRMED 미달.** ⚠️ **Fotmob 라벨 오류 실증**: Fotmob이 이 항목을 "Likely / **Today** / The Athletic"으로 표시했으나 원문은 **08-08**이다 — SKILL.md가 경고한 Fotmob 라벨 신뢰 금지가 **티어뿐 아니라 날짜에도** 적용됨을 확인.','Marca(스페인 전국지, 원출처) via Matteo Moretto(준1티어) ; https://www.sportsmole.co.uk/football/aston-villa/transfer-talk/news/emery-wants-to-sign-italian-defender-immediately-as-aston-villa-bid-to-resolve-clear-issue_602381.html ; http://insidefutbol.com/2026/08/04/aston-villa-push-for-defender-as-he-weighs-his-options/722198/ ; https://www.eurosport.es/futbol/mercado-de-fichajes-2026/2026/aston-villa-interes-matteo-ruggeri-atletico-de-madrid_sto23325237/story.shtml ; https://uk.sports.yahoo.com/news/aston-villa-could-seal-immediate-101500950.html ; SofaScore /api/v1/player/965011/events/last/0 + /event/{eid}/player/965011/heatmap|statistics ; The Athletic(Jacob Tanswell, 1티어, 2026-08-04, paywall 미열람 — 인용 3매체 발행시각 일치로 확정) ; Marca(Isaac Suarez) 2026-08-04 via Sport Witness ; https://www.givemesport.com/aston-villa-identify-mattero-ruggeri-digne-replacement-transfer/ (2026-08-04) ; Tinti 발언 https://www.romaforever.it/2026/07/21/ruggeri-si-allontana-lagente-tinti-fa-chiarezza-sul-suo-futuro/ (2026-07-21) ; Total Football Analysis 스카우트리포트 2025-07-24(⚠️아탈란타 24/25 데이터) | https://www.marca.com (2026-08-05, via readastonvilla.com/2026/08/05/aston-villa-agree-20m-matteo-ruggeri-deal-as-final-hurdle-remains/) | https://insidefutbol.com/2026/08/05/aston-villa-move-blocked-for-now-as-definitive-yes-is-missing/ (Moretto)','MEDIUM-HIGH — 2티어(Marca, 원출처 직접 보도) + 준1티어(Moretto)가 오퍼 제출 단계를 보도. 1티어(Romano/Sky/BBC/Athletic) 직접 확인은 검색에서 미발견이라 HIGH 미충족. §2-0 발행일 검증 통과: 발행일 2026-08-04 확정, 나이 표기 24세가 실제(2002-07-11생 → 24세)와 일치, 병기 정황(그리말도 아틀레티코 입단·그리스만 올랜도 자유이적·랑글레 벤피카 임대·디뉴 PSG)도 현재 상태와 부합 → 1년 오차 함정 아님. 캐비앗: ⑴ 선수 결정 대기 상태로 무산 가능성 상존, ⑵ 2주 전 대리인 Tinti의 ''아틀레티코 잔류가 계획'' 발언(Sky Sport Italia)과 상충 — 오늘 보도가 더 최신이라 채택하되 상충 사실 명기, ⑶ 실측 표본이 25/26 시즌 종료분이라 아틀레티코 1년차 역할 기준(그리말도 영입 전). [2026-08-05 심층 추가 캐비앗] ⑷ 이적료 보도 충돌 — Cerchione €18m+€3m(최대 €21m, 구조 제시) vs The Athletic ~€25m(총액, 티어 우위). 어느 쪽도 다른 1티어가 복제하지 않았다. ⑸ 선수 측 의사 충돌 — 대리인 Tinti의 2026-07-21 Sky Sport Italia 발언 "아틀레티코에 남는다, 시장에 나와 있지 않다"가 08-03~04 훈련 제외·대리인 마드리드 방문과 정면 충돌. 협상 포지셔닝이었을 가능성이 높으나 선수 본인의 이탈리아 복귀 선호의 흔적일 가능성도 배제 못 함 — 확정 근거 없음. ⑹ 인용 함정 2건 명기: (a) Total Football Analysis 스카우트 리포트는 제목이 "Atletico Madrid 2025/2026"이나 실제 발행 2025-07-24·데이터는 아탈란타 24/25 기반이다 — 25/26 아틀레티코 평가로 인용 금지. (b) BirminghamWorld "Fabrizio Romano confirms £17m deal"은 2025-06 아탈란타→아틀레티코 이적 건으로, 빌라 딜의 1티어 근거로 오인하기 쉬운 재순환 기사다. ⑺ 08-04 기록의 발행일 교차검증 항목 중 "그리스만 올랜도 자유이적"은 2026-08-05 재확인에서 검증 실패(그리즈만은 여전히 아틀레티코 스쿼드에 포함) — 나머지 3개 병기 정황(그리말도 입단·랑글레 벤피카·디뉴 PSG)은 유효하므로 발행일 판정 자체는 유지하되 이 항목은 근거에서 제외한다. ⑻ 실측 한계: @dom/@tight 및 국면(possH/possL) 분리 표본이 없어 에메리의 "풀백은 한 명씩만 전진" 모듈레이션 수행 가능 여부는 판정 불가(디뉴·마첸은 해당 행 보유). ⑼ 부상 이력 — 2021-09~2023-04 근육 부상 클러스터(최장 4개월) 이후 2024년부터 안정화, 25/26 아틀레티코 시즌 부상 기록 없음. 내구성 리스크 LOW-MEDIUM. ⑽ 신체·산출 맥락: 187cm 왼발, 공중볼 승률 92.1퍼센타일(24/25 5대리그 LWB 대비) — The Athletic이 말한 "physical profile"의 정량 근거. 25/26 라리가 26경기(20선발) 1,775분 0골 3도움, 크로스 95회(4.8회/90), 태클 1.88·인터셉트 1.01·클리어 3.19/90. 세리에A 30경기 3도움 → 라리가 26경기 3도움으로 3백 윙백→4백 풀백 전환에도 분당 생산성 유지. | 2026-08-06: 합의 보도는 2티어 복수(Marca·Uria·Moretto) 일치, 1티어 직접 확인은 The Athletic 관심 보도까지. Romano "here we go" 미발행 — CONFIRMED 아님. Mundo Deportivo 원문 발행일 미확정이라 last_news_date는 확인된 08-05로 기록.','루헤리','2026-08-09');
